import gzip
import logging
import lzma
import os
import re
import shutil
import tarfile
import zipfile

from typing import Optional


def archive_opener_selector(archive_path):
    """
    Returns an appropriate file opener based on the file extension of the archive file.

    Parameters:
    archive_path (str): The path to the archive file.

    Returns:
    file opener: An appropriate file opener for the archive file.

    Raises:
    NotArchiveFileError: If the file is not an archive file.
    """

    class NotArchiveFileError(Exception):
        """Raised when the file is not an archive file"""
        pass

    if archive_path.endswith(".zip"):
        return zipfile.ZipFile(archive_path)
    elif archive_path.endswith(".tar.gz") or archive_path.endswith(".tgz"):
        return tarfile.open(archive_path, "r:gz")
    elif archive_path.endswith(".tar"):
        return tarfile.open(archive_path, "r:")
    elif archive_path.endswith(".gz"):
        return gzip.open(archive_path, "rb")
    elif archive_path.endswith(".xz"):
        return lzma.open(archive_path, "rb")
    else:
        raise NotArchiveFileError()


def is_archive_file(open_file_name):
    """
    Checks if a file is an archive file based on its extension.

    Parameters:
    open_file_name (str): The name of the file to check.

    Returns:
    bool: True if the file is an archive file, False otherwise.
    """
    return any(open_file_name.endswith(archive_file_type) for archive_file_type in [".zip", ".tar", ".tar.gz", ".tgz"])


def is_compressed_file(open_file_name):
    """
    Checks if a file is a compressed file based on its extension.

    Parameters:
    open_file_name (str): The name of the file to check.

    Returns:
    bool: True if the file is a compressed file, False otherwise.
    """
    return any(open_file_name.endswith(compressed_file_type) for compressed_file_type in [".gz", ".xz"])


def get_archive_files_list(archive_file):
    """
    Returns a dictionary of file names and their sizes in the archive file.

    Parameters:
    archive_file (file): The archive file to get the list of files from.

    Returns:
    dict: A dictionary of file names and their sizes.
    """
    if isinstance(archive_file, zipfile.ZipFile):
        return {file.filename: file.file_size for file in archive_file.infolist()}
    elif isinstance(archive_file, tarfile.TarFile):
        return {file.name: file.size for file in archive_file.getmembers()}


class SnapshotAnalyzer:
    """
    A class used to analyze snapshot files.

    This class provides methods for setting up directories for snapshot analysis and for analyzing the snapshot.

    Attributes:
        snapshot_extract_directory (str): The directory where the extracted snapshot will be stored.
        logs_directory (str): The directory where the analysis logs will be stored.
        temporary_directory (str): A temporary directory used during the analysis.
    """
    snapshot_extract_directory = None
    logs_directory = None
    temporary_directory = None

    @classmethod
    def set_directories(cls, snapshot_file_path):
        """
        Set up the directories for snapshot analysis.

        This method sets the `snapshot_extract_directory`, `logs_directory`, and `temporary_directory` class attributes
        based on the provided snapshot file path.

        Args:
            snapshot_file_path (str): The path to the snapshot file to analyze.
        """
        cls.snapshot_extract_directory = os.path.join(os.path.dirname(snapshot_file_path), "snapshot_analysis",
                                                      "extracted_snapshot")
        cls.temporary_directory = os.path.join(os.path.dirname(snapshot_file_path), "temporary_snapshot")
        cls.logs_directory = os.path.join(os.path.dirname(snapshot_file_path), "snapshot_analysis", "analysis_logs")

    @classmethod
    def analyze_snapshot(cls, snapshot_file_path):
        """
        Analyze the snapshot.

        This method sets up the directories for snapshot analysis and then analyzes the snapshot.

        Args:
            snapshot_file_path (str): The path to the snapshot file to analyze.
        """
        cls.set_directories(snapshot_file_path)
        cls.snapshot_extractor(snapshot_file_path, cls.snapshot_extract_directory, cls.logs_directory,
                               cls.temporary_directory)
        cls.analyze_snapshot_logs(cls.snapshot_extract_directory, cls.logs_directory)
        cls.remove_extracted_snapshot()

    @classmethod
    def remove_extracted_snapshot(cls):
        shutil.rmtree(cls.snapshot_extract_directory, ignore_errors=True)

    @staticmethod
    def snapshot_extractor(snapshot_single_file, snapshot_extract_directory, logs_directory,
                           temporary_extract_directory):
        """
        Extracts files from a snapshot file based on certain conditions.

        Parameters:
        snapshot_single_file (str): The path to the snapshot file.
        target_extract_dir (Optional[str]): The path to the directory where the extracted files will be stored.
        Defaults to None.

        Returns:
        None
        """
        searched_substring = ["_crash", "_crashdumps", "runtime", "startup", "syslog", "messages", "LFS", "HWAPI",
                              "SYSTEM", "linux_logs"]
        ignored_file_names = ["RMOD", "bmux", "sysinfo"]

        def set_snapshot_extractor_logger(log_path):
            """
            Set up a logger for the snapshot extractor.

            This function creates a logger with the name "snapshot_extractor", sets its level to DEBUG,
            and assigns a file handler to it. The file handler writes the logs to a file named
            "snapshot_extractor.log" in the specified directory. If the directory does not exist,
            it is created. Any existing handlers are removed before the new handler is added.

            Args:
                log_path (str): The directory where the log file will be created.

            Returns:
                logging.Logger: The configured logger.
            """
            logger = logging.getLogger("snapshot_extractor")
            logger.setLevel(logging.DEBUG)
            formatter = logging.Formatter("%(asctime)s - %(message)s")
            for handler in logger.handlers:
                logger.removeHandler(handler)
            os.makedirs(log_path, exist_ok=True)
            logger_file_handler = logging.FileHandler(os.path.join(log_path, "snapshot_extractor.log"))
            logger_file_handler.setFormatter(formatter)
            logger_file_handler.setLevel(logging.DEBUG)
            logger.addHandler(logger_file_handler)
            logger.propagate = False
            return logger

        extractor_logger = set_snapshot_extractor_logger(logs_directory)

        def file_extractor(archive, file_name, path):
            if "/" in file_name:
                file_path = os.path.join(snapshot_extract_directory, path, file_name.rsplit("/", 1)[0])
            else:
                file_path = os.path.join(snapshot_extract_directory, path)
            os.makedirs(file_path, exist_ok=True)
            if ":" in file_name:
                if isinstance(archive, zipfile.ZipFile):
                    file_content = archive.read(file_name)
                else:
                    file_content = archive.extractfile(file_name).read()
                with open(os.path.join(snapshot_extract_directory, path, file_name.replace(":", "_")),
                          "wb") as extracted_file:
                    extracted_file.write(file_content)
            else:
                archive.extract(file_name, os.path.join(snapshot_extract_directory, path))

        def temp_extract_file(arch_file, file, path: Optional[str] = None):
            if path:
                extract_path = os.path.join(temporary_extract_directory, path, file.split(".", 1)[0])
            else:
                extract_path = os.path.join(temporary_extract_directory, file.split(".", 1)[0])
            extractor_logger.debug(f"Extracting {file} do {extract_path}")
            if file.endswith(".zip"):
                if "crash" in file:
                    arch_file.extract(file, os.path.join(logs_directory, "crashes"))
                return arch_file.extract(file, extract_path) or os.path.join(extract_path, file)
            else:
                if "crash" in file:
                    arch_file.extract(file, os.path.join(logs_directory, "crashes"))
                arch_file.extract(file, extract_path)
                return os.path.join(extract_path, file)

        def is_searched_file(file_name):
            for substring in searched_substring:
                if substring in file_name:
                    return True

        def is_ignored_file(file_name):
            for ignored_file_name in ignored_file_names:
                if ignored_file_name in file_name:
                    return True

        def file_handler(file, ext_path=""):
            for single_file_name, single_file_size in get_archive_files_list(file).items():
                if single_file_size and (
                        is_searched_file(single_file_name) or is_searched_file(ext_path)) and \
                        not is_ignored_file(single_file_name):
                    if is_archive_file(single_file_name):
                        with archive_opener_selector(temp_extract_file(file, single_file_name, ext_path)) as archive:
                            extract_path = os.path.join(ext_path, single_file_name.split(".")[0])
                            file_handler(archive, extract_path)
                    else:
                        os.makedirs(os.path.join(snapshot_extract_directory, ext_path), exist_ok=True)
                        if is_compressed_file(single_file_name):
                            with archive_opener_selector(
                                    temp_extract_file(file, single_file_name, ext_path)) as compressed_file:
                                copy_file_decompressed_file(compressed_file, ext_path,
                                                            str(re.split(r".gz|.xz", single_file_name)[0]))
                        else:
                            file_extractor(file, single_file_name, ext_path)

        def copy_file_decompressed_file(file, path, file_name):
            extractor_logger.debug(
                f"Coping file {file_name} do {os.path.join(snapshot_extract_directory, path, file_name)}")
            if "/" in file_name:
                file_path = os.path.join(snapshot_extract_directory, path, file_name.rsplit("/", 1)[0])
            else:
                file_path = os.path.join(snapshot_extract_directory, path)
            os.makedirs(file_path, exist_ok=True)
            with open(os.path.join(snapshot_extract_directory, path, file_name), "wb") as kon:
                shutil.copyfileobj(file, kon)

        def bts_part_extractor(bts_part_file, path=""):
            for log_file_name, log_file_size in get_archive_files_list(bts_part_file).items():
                if log_file_size:
                    extract_path = os.path.join(path, log_file_name.split(".")[0])
                    if is_searched_file(log_file_name) and not is_ignored_file(log_file_name):
                        if is_compressed_file(log_file_name) or is_archive_file(log_file_name):
                            with archive_opener_selector(
                                    temp_extract_file(bts_part_file, log_file_name, path)) as archive:
                                if is_compressed_file(log_file_name):
                                    copy_file_decompressed_file(archive, path,
                                                                str(re.split(r".gz|.xz", log_file_name)[0]))
                                elif is_archive_file(log_file_name):
                                    file_handler(archive, extract_path)
                        else:
                            os.makedirs(os.path.join(snapshot_extract_directory, path), exist_ok=True)
                            file_extractor(bts_part_file, log_file_name, path)

        with archive_opener_selector(snapshot_single_file) as snapshot_file:
            for bts_part in get_archive_files_list(snapshot_file).keys():
                if bts_part.endswith(".zip") and not is_ignored_file(bts_part):
                    with archive_opener_selector(temp_extract_file(snapshot_file, bts_part)) as bts_part_archive:
                        bts_part_extractor(bts_part_archive, bts_part.split(".")[0])
                    shutil.rmtree(os.path.join(temporary_extract_directory, bts_part.split(".", 1)[0]))
            shutil.rmtree(temporary_extract_directory)

    @staticmethod
    def analyze_snapshot_logs(extracted_snapshot_dir, logs_dir):
        """
        Analyze the snapshot logs.

        This function searches for specific patterns in the snapshot logs and writes the results
        to a log file named "all_exceptions_results.log" in the specified directory.

        Args:
            extracted_snapshot_dir (str): The directory containing the snapshot logs to analyze.
            logs_dir (str): The directory where the results log file will be created.
        """
        searched_snapshot_pattern_list = [
            "Error Handler exception report",
            "FATAL DSPHWAPI ERROR",
            "High AaIPC message pool",
            "Please contact the owner of",
            "Invalid memory reference",
            r"fatality\s{3,}:",
            r"code\s{3,}:",
            r"description\s{3,}:",
            r"EU name\s{3,}:",
            r"EE id \(OS\)\s{3,}:",
            r"EU id\s{3,}:",
            r"EU id \(OS\)/s{3,}:",
            r"EE command\s{3,}:",
            r"filename\s{3,}:",
            r"extra\s{3,}:",
            "Abort signal received",
            "Bus error",
            "ERR: #",
            r"coreNotifier\(\)"
        ]

        searched_snapshot_pattern = "|".join(searched_snapshot_pattern_list)
        os.system(
            f'find {extracted_snapshot_dir} -type f '
            f'| xargs grep -HrE \'{searched_snapshot_pattern}\' > {logs_dir}/all_exceptions_results.log ')
